import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type FocusRevealListProps = Record<string, any>;

const FocusRevealList: React.FC<FocusRevealListProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 9,
  items = ["WHAT IS MARKETING?", "BUILDING TRUST", "CREATING VALUE"],
  primaryColor = "#ff0000",
  textColor = "#ffffff",
  dimmedColor = "#4a4a4a",
  blurStrength = 15,
  itemSpacing = 2000,
  timelineSpacing = 350,
}) => {
  useFontLoader(["Oswald"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timing Logic
  const numItems = items.length;
  // Calculate keyframes dynamically based on number of items
  const scrollPosition = useMemo(() => {
    if (numItems <= 1) return 0;

    const inputRange = [];
    const outputRange = [];
    
    // Total logical units
    const timePerItem = totalFrames / numItems;
    const holdTime = timePerItem * 0.6;
    const slideTime = timePerItem * 0.4;
    
    let currentFrame = 0;
    
    for (let i = 0; i < numItems; i++) {
        // Hold Phase for item i
        inputRange.push(currentFrame);
        outputRange.push(i);
        
        currentFrame += holdTime;
        inputRange.push(currentFrame);
        outputRange.push(i);
        
        // Slide Phase to i+1 (if not last)
        if (i < numItems - 1) {
            currentFrame += slideTime;
        }
    }
    
    const calculatedTotal = inputRange[inputRange.length - 1];
    const normalizedInput = inputRange.map(f => (f / calculatedTotal) * totalFrames);
    
    return interpolate(frame, normalizedInput, outputRange, {
        easing: Easing.bezier(0.65, 0, 0.35, 1), // "Editorial" smooth ease
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
    });
  }, [frame, numItems, totalFrames]);

  // Visual Constants
  const fontScale = width / 1920; 
  const fontSize = 160 * fontScale;
  const listY = height * 0.5; // Perfectly centered vertically
  
  // Progress Bar Constants
  const barY = height * 0.82;
  const nodeSize = 60 * fontScale;
  
  // Calculate bar width based on explicit spacing per step
  // This ensures equal gaps between nodes regardless of count (until max width)
  const spacingScaled = timelineSpacing * fontScale;
  const maxBarWidth = width * 0.9;
  const barWidth = numItems > 1 
    ? Math.min(maxBarWidth, (numItems - 1) * spacingScaled) 
    : 0;
    
  const barLeft = (width - barWidth) / 2;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
        
        {/* --- List Items Container --- */}
        <AbsoluteFill>
            {items.map((item, index) => {
                // Calculate position relative to center
                const xOffset = (index - scrollPosition) * itemSpacing;
                const xPos = (width / 2) + xOffset;
                
                // Calculate Blur & Opacity based on distance from current focus (scrollPosition)
                const dist = Math.abs(index - scrollPosition);
                
                // Blur logic
                const blur = interpolate(dist, [0, 0.8], [0, blurStrength], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp"
                });
                
                // Opacity logic
                const opacity = interpolate(dist, [0, 1, 2], [1, 0.5, 0.2], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp"
                });
                
                // Culling
                if (xPos < -width || xPos > width * 2) return null;

                return (
                    <div
                        key={index}
                        style={{
                            position: "absolute",
                            left: 0,
                            top: listY,
                            width: "auto", // Allow width to fit content for better centering logic
                            transform: `translateX(${xPos}px) translate(-50%, -50%)`,
                            textAlign: "center",
                            fontFamily: "Oswald, sans-serif",
                            fontSize: fontSize,
                            fontWeight: 700,
                            color: textColor,
                            textTransform: "uppercase",
                            letterSpacing: "-0.02em",
                            whiteSpace: "nowrap",
                            filter: `blur(${blur}px)`,
                            opacity: opacity,
                            willChange: "transform, filter, opacity",
                        }}
                    >
                        {item}
                    </div>
                );
            })}
        </AbsoluteFill>

        {/* --- Progress Bar / Timeline --- */}
        <AbsoluteFill>
            <div style={{
                position: "absolute",
                top: barY,
                left: barLeft,
                width: barWidth,
                height: 10,
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
            }}>
                {/* Background Line */}
                <div style={{
                    position: "absolute",
                    left: 0,
                    top: "50%",
                    marginTop: -4,
                    width: "100%",
                    height: 8,
                    backgroundColor: dimmedColor,
                    borderRadius: 4,
                    zIndex: 0,
                }} />
                
                {/* Active Progress Line (fills up to current item) */}
                <div style={{
                    position: "absolute",
                    left: 0,
                    top: "50%",
                    marginTop: -4,
                    width: `${Math.min(100, (scrollPosition / (numItems - 1)) * 100)}%`,
                    height: 8,
                    backgroundColor: "#ffffff",
                    borderRadius: 4,
                    zIndex: 1,
                    transition: "width 0.1s linear" // Smooth fill
                }} />

                {/* Nodes */}
                {items.map((_, i) => {
                    // Node active state calculation
                    const dist = Math.abs(i - scrollPosition);
                    const isActive = dist < 0.5; // Threshold for snapping color
                    
                    // Colors
                    const circleBg = isActive ? primaryColor : dimmedColor;
                    const numberColor = "#ffffff";
                    const scale = isActive ? 1.2 : 1.0;
                    
                    return (
                        <div key={`node-${i}`} style={{
                            width: nodeSize,
                            height: nodeSize,
                            borderRadius: "50%",
                            backgroundColor: circleBg,
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            zIndex: 2,
                            transform: `scale(${scale})`,
                            transition: "background-color 0.3s, transform 0.3s",
                            border: `2px solid ${backgroundColor}`, // Stroke to separate from line
                            boxShadow: isActive ? "0 4px 12px rgba(0,0,0,0.3)" : "none"
                        }}>
                            <span style={{
                                fontFamily: "Oswald, sans-serif",
                                fontWeight: 700,
                                fontSize: nodeSize * 0.6,
                                color: numberColor,
                                lineHeight: 1
                            }}>
                                {i + 1}
                            </span>
                        </div>
                    );
                })}
            </div>
        </AbsoluteFill>
        
        {/* --- Optional Vignette for Focus --- */}
        {!transparentBackground && (
             <AbsoluteFill style={{
                 background: `radial-gradient(circle, transparent 40%, ${backgroundColor}E6 100%)`,
                 pointerEvents: "none",
                 zIndex: 10
             }}/>
        )}

    </AbsoluteFill>
  );
};

export default FocusRevealList;